{"implementation":"def solve(case):
    segments = list(case.get("segments", []))
    n = len(segments)
    budget = int(case.get("budget", 0))

    minimums = [int(seg.get("minimum", 0)) for seg in segments]
    capacities = [int(seg.get("capacity", minimums[i])) for i, seg in enumerate(segments)]
    weights = [int(seg.get("importance", 0)) for seg in segments]

    allocations = [0] * n
    if n == 0 or budget <= 0:
        return {"allocations": allocations, "by_name": {}, "total": 0}

    caps = [max(0, capacities[i]) for i in range(n)]
    mins = [min(max(0, minimums[i]), caps[i]) for i in range(n)]
    total_capacity = sum(caps)
    target = min(max(0, budget), total_capacity)

    if target >= sum(mins):
        allocations = mins[:]
        remaining = target - sum(allocations)
    else:
        remaining = target

    def distribute(amount, base, limits, active_weights):
        result = base[:]
        left = amount
        while left > 0:
            eligible = [i for i in range(n) if result[i] < limits[i]]
            if not eligible:
                break
            weight_sum = sum(max(0, active_weights[i]) for i in eligible)
            if weight_sum <= 0:
                for i in eligible:
                    if left <= 0:
                        break
                    result[i] += 1
                    left -= 1
                continue

            shares = []
            assigned = 0
            for i in eligible:
                capacity_left = limits[i] - result[i]
                exact_num = left * max(0, active_weights[i])
                floor_share = exact_num // weight_sum
                give = min(capacity_left, floor_share)
                result[i] += give
                assigned += give
                shares.append((exact_num / weight_sum - floor_share, -i, i))

            left -= assigned
            if left <= 0:
                break

            progressed = False
            for _, _, i in sorted(shares, reverse=True):
                if left <= 0:
                    break
                if result[i] < limits[i]:
                    result[i] += 1
                    left -= 1
                    progressed = True
            if not progressed:
                break
        return result

    if target < sum(mins):
        allocations = distribute(target, [0] * n, mins, weights)
    elif remaining > 0:
        allocations = distribute(remaining, allocations, caps, weights)

    by_name = {str(segments[i].get("name", "")): int(allocations[i]) for i in range(n)}
    return {"allocations": [int(x) for x in allocations], "by_name": by_name, "total": int(sum(allocations))}
"}
